// Match page anchors rather than raw scroll percentages: the two views have different heights.
function bindSyncScroll(){
 const left=document.getElementById('krSource'),right=document.getElementById('krResults');
 const expected=new WeakMap();
 function anchors(container){
  const rect=container.getBoundingClientRect();
  const nodes=container===left?container.querySelectorAll('[data-source-page]'):container.querySelectorAll(state.mode==='parsed'?'[data-parsed-page]':'[data-card]');
  const seen=new Set();
  return Array.from(nodes).flatMap(node=>{
   const page=container===left?Number(node.dataset.sourcePage):state.mode==='parsed'?Number(node.dataset.parsedPage):blocks.find(b=>b.id===chunks.find(c=>c.id===node.dataset.card).ids[0]).page;
   if(seen.has(page))return [];seen.add(page);
   return [{page,top:Math.max(0,node.getBoundingClientRect().top-rect.top+container.scrollTop-16)}];
  });
 }
 function sync(from,to){
  if(!state.syncScroll||state.tocNavigating||(state.mode==='parsed'&&state.parsedTab!=='text'))return;
  const a=anchors(from),b=anchors(to);if(!a.length||!b.length)return;
  const maxFrom=from.scrollHeight-from.clientHeight,maxTo=to.scrollHeight-to.clientHeight;
  let top=0;
  if(from.scrollTop>=maxFrom-1&&maxFrom>0)top=maxTo;
  else if(from.scrollTop>0){
   let i=0;while(i<a.length-1&&a[i+1].top<=from.scrollTop)i++;
   const start=a[i],end=a[i+1];
   const match=b.find(x=>x.page===start.page)||b.reduce((best,x)=>Math.abs(x.page-start.page)<Math.abs(best.page-start.page)?x:best,b[0]);
   const next=end&&b.find(x=>x.page===end.page);
   const progress=Math.max(0,Math.min(1,(from.scrollTop-start.top)/Math.max(1,(end?end.top:maxFrom)-start.top)));
   top=match.top+progress*((next?next.top:maxTo)-match.top);
  }
  top=Math.max(0,Math.min(maxTo,top));
  if(Math.abs(to.scrollTop-top)>.5){to.scrollTop=top;expected.set(to,to.scrollTop)}
 }
 [left,right].forEach(from=>from.addEventListener('scroll',()=>{
  if(expected.has(from)){const target=expected.get(from);expected.delete(from);if(Math.abs(from.scrollTop-target)<1)return}
  sync(from,from===left?right:left);
 },{passive:true}));
 document.getElementById('krSyncScroll').onclick=()=>{
  state.syncScroll=!state.syncScroll;
  const button=document.getElementById('krSyncScroll');button.classList.toggle('on',state.syncScroll);button.setAttribute('aria-checked',String(state.syncScroll));
  expected.delete(left);expected.delete(right);
  sync(left,right);
 };
 state.alignScroll=()=>sync(left,right);
}

